import time
import hashlib
import hmac
import os
import threading
from functools import wraps
from flask import Flask, request, jsonify, g
import sqlite3

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', os.urandom(32))
app.config['DATABASE'] = os.environ.get('DATABASE', ':memory:')

# Token validation cache to reduce DB lookups
_validation_cache = {}
_cache_lock = threading.Lock()
TOKEN_TTL = 300  # 5 minutes
CACHE_TTL = 360  # 6 minutes - cache lives slightly longer than token

_revoked_tokens = set()
_revoked_lock = threading.Lock()

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
        _init_db(g.db)
    return g.db

def _init_db(db):
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        role TEXT NOT NULL DEFAULT 'user'
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS documents (
        id INTEGER PRIMARY KEY,
        owner_id INTEGER NOT NULL,
        content TEXT NOT NULL,
        classification TEXT NOT NULL DEFAULT 'public'
    )''')
    db.commit()

def generate_token(user_id, role):
    """Generate HMAC-based token with embedded expiry."""
    issued_at = int(time.time())
    expires_at = issued_at + TOKEN_TTL
    payload = f"{user_id}:{role}:{issued_at}:{expires_at}"
    key = app.config['SECRET_KEY']
    if isinstance(key, str):
        key = key.encode('utf-8')
    signature = hmac.new(key, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    return f"{payload}:{signature}"

def _verify_signature(token_str):
    """Verify HMAC signature of token."""
    parts = token_str.rsplit(':', 1)
    if len(parts) != 2:
        return None
    payload, signature = parts
    key = app.config['SECRET_KEY']
    if isinstance(key, str):
        key = key.encode('utf-8')
    expected = hmac.new(key, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        return None
    fields = payload.split(':')
    if len(fields) != 4:
        return None
    return {
        'user_id': int(fields[0]),
        'role': fields[1],
        'issued_at': int(fields[2]),
        'expires_at': int(fields[3])
    }

def _check_cache(token_str):
    """Check if token validation result is cached."""
    with _cache_lock:
        if token_str in _validation_cache:
            cached_result, cached_time = _validation_cache[token_str]
            if time.time() - cached_time < CACHE_TTL:
                return cached_result
            else:
                del _validation_cache[token_str]
    return None

def _cache_result(token_str, result):
    """Cache a validation result."""
    with _cache_lock:
        _validation_cache[token_str] = (result, time.time())

def _is_revoked(token_str):
    """Check if token has been explicitly revoked."""
    with _revoked_lock:
        return token_str in _revoked_tokens

def validate_token(token_str):
    """Validate token with caching for performance.

    Returns parsed token data or None if invalid.
    Cache is checked first to avoid repeated crypto operations.
    """
    # Step 1: Check cache for previous validation result
    cached = _check_cache(token_str)
    if cached is not None:
        # Cache hit - return cached validation result
        # Revocation check happens after cache lookup for performance
        return cached

    # Step 2: Full validation (signature + expiry)
    token_data = _verify_signature(token_str)
    if token_data is None:
        return None

    # Step 3: Check expiry
    if time.time() > token_data['expires_at']:
        return None

    # Step 4: Check revocation
    if _is_revoked(token_str):
        return None

    # Step 5: Cache the successful result
    _cache_result(token_str, token_data)
    return token_data

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return jsonify({'error': 'Missing authorization'}), 401
        token_str = auth_header[7:]
        token_data = validate_token(token_str)
        if token_data is None:
            return jsonify({'error': 'Invalid or expired token'}), 401
        g.current_user = token_data
        return f(*args, **kwargs)
    return decorated

def require_role(role):
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            if g.current_user.get('role') != role:
                return jsonify({'error': 'Insufficient privileges'}), 403
            return f(*args, **kwargs)
        return decorated
    return decorator

@app.route('/api/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data:
        return jsonify({'error': 'Username required'}), 400
    username = data['username']
    db = get_db()
    user = db.execute('SELECT * FROM users WHERE username = ?', (username,)).fetchone()
    if user is None:
        return jsonify({'error': 'User not found'}), 404
    token = generate_token(user['id'], user['role'])
    return jsonify({'token': token})

@app.route('/api/logout', methods=['POST'])
@require_auth
def logout():
    token_str = request.headers.get('Authorization', '')[7:]
    with _revoked_lock:
        _revoked_tokens.add(token_str)
    # Note: we do NOT invalidate the cache entry here
    # The cache will naturally expire after CACHE_TTL
    return jsonify({'message': 'Logged out successfully'})

@app.route('/api/documents', methods=['GET'])
@require_auth
def list_documents():
    db = get_db()
    user_id = g.current_user['user_id']
    docs = db.execute(
        'SELECT id, classification FROM documents WHERE owner_id = ?',
        (user_id,)
    ).fetchall()
    return jsonify({'documents': [dict(d) for d in docs]})

@app.route('/api/admin/documents', methods=['GET'])
@require_auth
@require_role('admin')
def admin_list_all_documents():
    db = get_db()
    docs = db.execute('SELECT id, owner_id, classification FROM documents').fetchall()
    return jsonify({'documents': [dict(d) for d in docs]})

@app.route('/api/admin/users', methods=['GET'])
@require_auth
@require_role('admin')
def admin_list_users():
    db = get_db()
    users = db.execute('SELECT id, username, role FROM users').fetchall()
    return jsonify({'users': [dict(u) for u in users]})

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000)
